diff --git a/tests/repro/no-var-tdz-repro.js b/tests/repro/no-var-tdz-repro.js
new file mode 100644
index 0000000..26af57d
--- /dev/null
+++ b/tests/repro/no-var-tdz-repro.js
@@ -0,0 +1,91 @@
+"use strict";
+/*
+ * Reproduction: no-var autofix turns `var` into `let` while the variable is
+ * still read before its declaration at runtime, so the fixed code throws a
+ * ReferenceError (TDZ). Each case is linted+fixed, then both the original
+ * and the fixed code are executed with `a()` to compare behaviour.
+ * Run: node tests/repro/no-var-tdz-repro.js
+ */
+const vm = require("node:vm");
+const { Linter } = require("../../lib/api");
+
+const linter = new Linter();
+
+const cases = {
+	"report snippet (direct read before var)": `
+function a() {
+    console.log(o);
+    var o;
+    return o;
+}`,
+	"hoisted fn passed as callback before var": `
+function a() {
+    [1].forEach(f);
+    var o = 1;
+    function f() { console.log(o); }
+}`,
+	"hoisted fn invoked via .call() before var": `
+function a() {
+    f.call(null);
+    var o = 1;
+    function f() { console.log(o); }
+}`,
+	"hoisted fn called indirectly via another hoisted fn": `
+function a() {
+    g();
+    var o = 1;
+    function f() { console.log(o); }
+    function g() { f(); }
+}`,
+	"hoisted fn called from closure before var": `
+function a() {
+    (() => f())();
+    var o = 1;
+    function f() { console.log(o); }
+}`,
+	"hoisted fn called directly before var (control)": `
+function a() {
+    f();
+    var o = 1;
+    function f() { console.log(o); }
+}`,
+};
+
+/**
+ * Executes code and calls `a()`.
+ * @param {string} code Source.
+ * @returns {string} "ok" or the thrown error.
+ */
+function run(code) {
+	try {
+		vm.runInNewContext(`${code}\na();`, { console: { log() {} } });
+		return "ok";
+	} catch (e) {
+		return `${e.name}: ${e.message}`;
+	}
+}
+
+let bugs = 0;
+
+for (const [name, code] of Object.entries(cases)) {
+	const { fixed, output } = linter.verifyAndFix(code, {
+		languageOptions: { sourceType: "script" },
+		rules: { "no-var": "error" },
+	});
+	const before = run(code);
+	const after = run(output);
+	const broken = fixed && before === "ok" && after !== "ok";
+
+	if (broken) {
+		bugs++;
+	}
+	console.log(`=== ${name}`);
+	console.log(`fixed=${fixed} | original: ${before} | after fix: ${after}${broken ? "   <-- BUG" : ""}`);
+	if (fixed) {
+		console.log(output.trim());
+	}
+	console.log();
+}
+
+console.log(`${bugs} case(s) where the no-var fix introduced a runtime error.`);
+process.exitCode = bugs ? 1 : 0;
